class ProductSdk:
  '''
    the main class for interacting with product endpoint
    user/pw are optional
  '''
  def __init__(self,
               branch:str = 'dev-manual',
               user:Optional[str] = None,
               pw:Optional[str] = None,
               region:str = 'ap-southeast-1',
               connect_timeout:float = 10,
               read_timeout:float = 30):
    validateConfig(branch, region)
    self.branchName = branch
    self.functionNames = FunctionNames(branchName = branch)
    self.lambdaClient = Lambda(user =user, pw=pw, region = region)
    # vps-up7: lambdasdk builds its boto3 client with no Config, so a stalled call could hang forever; the same
    # client with timeouts and standard retries, under lambdasdk's own invoke()
    self.lambdaClient.lambdaClient = boto3.client(
      'lambda', region_name = region, aws_access_key_id = user, aws_secret_access_key = pw,
      config = Config(connect_timeout = connect_timeout, read_timeout = read_timeout,
                      retries = {'mode': 'standard', 'max_attempts': 3}))
    self.timeouts = (connect_timeout, read_timeout)
    self.user = user; self.pw = pw; self.region = region

  @staticmethod
  def returnLambdaResponse(lambdaResponse:dict, functionName:Optional[str] = None):
    '''the parsed body; raises ProductSdkError (it used to log and return None)'''
    return parseLambdaResponse(lambdaResponse, functionName)

  @staticmethod
  def printFirst(inputDict:dict):
    return next(iter(inputDict.items()))

  def _invoke(self, functionName:str, payload:Any, invocationType:str = InvocationType.requestResponse):
    '''invoke a function; a failed invoke (network, permissions, missing function) is a ProductSdkError'''
    try:
      return self.lambdaClient.invoke(functionName = functionName, input = payload, invocationType = invocationType)
    except Exception as e:
      raise ProductSdkError(f'invoking the lambda failed: {type(e).__name__}: {e}', functionName = functionName) from e

  def generalInvoke(self, functionName, payload):
    '''invoke and return the parsed body; ProductSdkError on a failed invoke, an unparseable or a non-200 response'''
    return parseLambdaResponse(self._invoke(functionName, payload), functionName)

  def updateWithS3(self, data,
                   inputKeyName:Optional[str] = None,
                   invocationType = InvocationType.event,
                   user= None, pw= None)->dict:
    '''upload products to the input bucket and start the ingestion function.

    Each call uploads under its own key (input-data-name-<uuid>) unless inputKeyName is given, so two callers
    never overwrite each other's upload (the fixed default key did). Returns
    {'key', 'bucket', 'functionName', 'invocationType', 'result'}: result is the parsed body for
    RequestResponse and None for an Event (async) invocation.'''
    _checkProducts(data)  # vps-28b: before anything is saved or invoked
    # put users if not specified
    user = user or self.user; pw = pw or self.pw
    key = inputKeyName or f'input-data-name-{uuid.uuid4().hex}'

    # extract function name and inputbucket name
    inputBucketName = self.functionNames.inputBucket()
    functionName = self.functionNames.updateS3()
    log.info(f'bucket is {inputBucketName}, key is {key}')

    # save data to s3
    ## convert keys to int
    filteredProducts = [{k:int(v) if k in INTCOLS else str(v) for k,v in product.items()}for product in data]

    try:
      S3.save(key = key,
              objectToSave = filteredProducts ,
              bucket = inputBucketName,
              user=user, pw=pw)
    except Exception as e:
      raise ProductSdkError(f'saving the input to s3 failed: {type(e).__name__}: {e}', functionName = functionName) from e
    log.info('data is saved to s3, invoking ingestion function')

    # call lambda function
    inputValue = Event(body = json.dumps({ 'key': key })).to_dict()
    lambdaResponse = self._invoke(functionName, inputValue, invocationType)
    result = None if invocationType == InvocationType.event else parseLambdaResponse(lambdaResponse, functionName)
    return {'key': key, 'bucket': inputBucketName, 'functionName': functionName,
            'invocationType': invocationType, 'result': result}


  def allQuery(self):
    functionName = self.functionNames.allQuery()
    url = self.generalInvoke(functionName, {})['url']
    result = retrieveJsonZl(url, timeout = self.timeouts)  # vps-up7
    return result
  def syncS3(self):
    '''force s3 to sync with the newly input data'''
    return self.generalInvoke(self.functionNames.dumpToS3(), {})

# Cell
def retrieveJsonZl(url, timeout = (10, 30)):
  '''download the zlib-compressed product table and read it with pandas (needed for allQuery only)'''
  response:requests.Response = requests.get(url, timeout = timeout)  # vps-up7
  if response.status_code != 200:
    raise ProductSdkError('downloading the product table failed', statusCode = response.status_code, body = response.text[:500])
  import io
  import pandas as pd
  jsonDb = zlib.decompress(response.content).decode()
  # vps-0qr: pandas 2.1 deprecated passing literal JSON as a str and pandas 3 reads a str as a file path
  return pd.read_json(io.StringIO(jsonDb), orient='split')

